function UIWorldBossRankRewardCellNode:RefreshHurtReward(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    CfUtils.FillText(self.TxtDamage, self._data.upperLimit)
    self:FillCommon()
    self:FillDrawStatus()
end

