function UIWorldBossRankRewardCellNode:RefreshRankReward(data, index)
    if not data then
        return
    end
    self._data = data
    self._cb = nil
    
    if checkNumber(self._data.type) == 1 then
        CfUtils.FillText(self.TxtRanking, self._data.upperLimit.."-"..self._data.lowerLimit)
    elseif  checkNumber(self._data.id) == 8 then
        CfUtils.FillText(self.TxtRanking, localize("未进入_num_", {_num_ = self._data.name}))
    else
        CfUtils.FillText(self.TxtRanking, self._data.name)
    end

    self:FillCommon()
end

function UIWorldBossRankRewardCellNode:FillRewards(data)
    if not data then
        return
    end
    --[[
    for i = 1, #data do
        if checkNumber(data[i].num) > 0 then
            data[i].numText = "x"..checkNumber(data[i].num)
        end
    end

    if self._uiFightReardsNodeScr then
        self._uiFightReardsNodeScr:Refersh(data, 0.45)
        self._uiFightReardsNodeScr:RefershSpacing(-58)
    end
    ]]
    
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    if scr then
        scr:FreshBaseUI(data)
    end
end

function UIWorldBossRankRewardCellNode:FillCommon()
    local rewards = RewardConfMgr:GetInstance():_GetRewardData(CfUtils.Split(self._data.reward), CfUtils.Split(self._data.rewardNum))
    self:FillRewards(rewards)
end

function UIWorldBossRankRewardCellNode:PlayAni(name)
    --[[
    local pos = self.Item.transform.localPosition
    self.Item.transform.localPosition = Vector3(pos.x, pos.y - 50, pos.z)
    self.Item.transform:DOLocalMoveY(pos.y, 0.3):SetDelay(0.06 * index)
    ]]
    local go = self.controller.gameObject.transform:Find("AnimRoot")
    CfUtils.PlayAnimator(go, name)
    --[[
    local group = self.chapterCell:GetComponent(typeof(CanvasGroup))
    self._co = cs_coroutine.start(function()
        coroutine.yield(WaitForSeconds(0.03 * self._ind))
        CfUtils.DoTween(0.3, function(updateValue)
            group.alpha = updateValue
        end)
    end)
    ]]
end

--领取奖励
function UIWorldBossRankRewardCellNode:OnBtnDrawReward()
    worldBossComponent:WorldBossdrawHurtRewardReq(self._data.id, function(rewardData)
        self:FillDrawStatus()
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardData } })   
        GameUtils.SetRedPointNum(Constants.RedPointConst.WorldBossReward, worldBossComponent:IsCanDrawReward())
        if self._cb then
            self._cb()
        end
    end)
end

function UIWorldBossRankRewardCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

